    "source": "https://finstack_quant.dev/schemas/instrument/1/fixed_income/asset_backed_facility.schema.json#/$defs/ReturnFloorSpec/properties/day_count",
    "description": "Day count convention for XIRR discounting. Defaults to Act/365F\n(matching `core::cashflow::xirr`) when `None`. Ignored for MOIC floors."
